.db ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:5px}
.close{margin-left:auto;width:38px;height:38px;border-radius:50%;border:1px solid var(--line);background:var(--card);font-size:18px}
.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:10px 16px;border-radius:10px;font-size:13.5px;z-index:90;max-width:min(560px,calc(100vw - 32px))}
.note{font-size:12px;color:var(--mut)}

@container (max-width:1240px){.build{grid-template-columns:210px minmax(0,1fr) 300px;gap:14px}.exec{grid-template-columns:1fr}}
@container (max-width:820px){.build{grid-template-columns:1fr}.col3{position:static;height:auto;min-height:0}.guide{min-height:420px}.rail{position:static;max-height:none;overflow:visible}.steps{display:flex;overflow-x:auto;gap:4px}.step{grid-template-columns:24px auto;min-width:max-content}.step .d,.step .badge{display:none}
  .krc{grid-template-columns:1fr 1fr}.trow,.thead{grid-template-columns:1fr 1fr;padding-left:16px}.thead{display:none}.proof,.addrow,.risk{padding-left:16px}.risk{grid-template-columns:1fr 1fr}
  .msh{grid-template-columns:36px minmax(0,1fr)}.msh>.acts{grid-column:1/-1}.est{grid-template-columns:1fr 1fr 1fr}.tc h2{font-size:23px}}

/* SKL OS frame: top bar with the two views as a segmented control, the round "i" (Page method) on the right */
.os2bar{display:flex;align-items:center;gap:14px;min-height:54px;padding-right:72px;position:relative}
.os2seg{display:inline-flex;gap:4px;padding:4px;background:#ECE8DF;border-radius:12px}
.os2seg button{border:0;background:none;border-radius:9px;padding:9px 18px;font-size:14.5px;font-weight:600;color:var(--ink2)}
.os2seg button[aria-pressed="true"]{background:#1B1B18;color:#FFFFFF}
.os2bar .ctx{color:var(--mut);font-size:13px}
.os2i{position:absolute;top:0;right:0;width:52px;height:52px;border-radius:50%;border:2px solid #1B1B18;background:#FFFFFF;color:#1B1B18;font-family:Fraunces,Georgia,serif;font-size:30px;font-weight:600;font-style:italic;line-height:1;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 10px rgba(27,27,24,.14)}
.os2 .rail,.os2 .col3{top:12px}
/* Build › Key Results: one row per key result, its milestones in their week; the Claude panel stays on the right */
.build.krmode{grid-template-columns:minmax(0,1fr) 420px}.build.krmode .rail{display:none}
@container (max-width:1240px){.build.krmode{grid-template-columns:minmax(0,1fr) 300px}}
@container (max-width:820px){.build.krmode{grid-template-columns:1fr}}
.kbw{padding:0;overflow-x:auto}
.kbg{display:grid;width:max-content;align-items:stretch}
.kbh{position:sticky;top:0;z-index:1;background:var(--card);padding:10px 8px;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:12px;font-weight:600;color:var(--ink2);display:flex;flex-direction:column;gap:2px}
.kbh small{font-family:var(--sans);font-weight:400;color:var(--mut2);font-size:11px}
.kbh.now{color:var(--gold2)}.kbh.kbk0{left:0;z-index:2;font-family:var(--sans);text-transform:uppercase;letter-spacing:.08em;font-size:11px;color:var(--mut)}
.kbo{padding:12px 14px 6px;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--gold2);background:var(--goldsoft);border-bottom:1px solid var(--line2)}
.kbo span{position:sticky;left:14px}
.kbe{padding:10px 14px;color:var(--mut);font-size:13px;border-bottom:1px solid var(--line2)}
.kbk{position:sticky;left:0;z-index:1;text-align:left;border:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line2);background:var(--card);padding:12px 14px;display:flex;flex-direction:column;gap:4px;font-size:13px;line-height:1.35;color:var(--ink)}
.kbk b{font-family:var(--mono);font-size:12px}.kbk:hover{background:var(--soft)}
.kbm2{display:flex;align-items:center;gap:6px;color:var(--mut);font-size:12px}
.kbc{border-bottom:1px solid var(--line2);border-right:1px dashed var(--line2);padding:8px 6px;display:flex;flex-direction:column;gap:6px;min-height:84px}
.kbc.now{background:var(--goldsoft)}.kbc.over{box-shadow:inset 0 0 0 2px var(--crit)}
.kbt{text-align:left;border:1px solid var(--line);border-left:3px solid var(--ink);border-radius:10px;background:var(--card);padding:7px 8px;display:flex;flex-direction:column;gap:5px;font-size:12.5px;line-height:1.3;color:var(--ink);box-shadow:var(--shadow)}
.kbt:hover{border-color:var(--ink)}.kbt.done{border-left-color:var(--ok)}.kbt.review{border-left-color:var(--late)}.kbt.notdone{border-left-color:var(--crit)}
.kbtt{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.kbto{display:flex;align-items:center;gap:5px;color:var(--mut);font-size:11.5px;flex-wrap:wrap}.kbto .av{width:18px;height:18px;font-size:8px}
.kba{align-self:flex-start;width:26px;height:26px;border-radius:50%;border:1px dashed var(--line);background:none;color:var(--mut2);font-size:15px;line-height:1;opacity:.55}
.kbc:hover .kba,.kba:focus-visible{opacity:1;border-color:var(--ink);color:var(--ink)}
.inp.ta{resize:vertical}

/* weekly measures of the targeted key result (Build, step 1) */
.meas{display:flex;flex-direction:column;gap:10px;border-top:1px solid var(--line);padding-top:12px}
.msv{width:100%;height:78px;background:var(--soft);border-radius:10px}
.mgrid{display:grid;grid-template-columns:repeat(13,minmax(0,1fr));gap:6px}
.mcell{display:flex;flex-direction:column;gap:4px;font-size:11px;font-weight:600;color:var(--mut);text-align:center}
.mcell.now span{color:var(--ink)}
.mcell input{width:100%;min-width:0;font:600 13px var(--mono);text-align:center;padding:7px 2px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink)}
.mcell.now input{border-color:var(--ink)}.mcell input:disabled{background:transparent;border-style:dashed}
@container (max-width:820px){.mgrid{grid-template-columns:repeat(7,minmax(0,1fr))}}
.mtw{overflow-x:auto;border:1px solid var(--line);border-radius:12px}
.mtab{border-collapse:collapse;width:100%;font-size:13px}
.mtab th,.mtab td{padding:6px 5px;border-bottom:1px solid var(--line);text-align:center;font-weight:600;color:var(--mut);font-size:11.5px}
.mtab .mtk{text-align:left;min-width:260px;max-width:320px;font-size:13px;color:var(--ink);font-weight:500;position:sticky;left:0;background:var(--card)}
.mtab .mtk small{display:block;color:var(--mut);font-size:11.5px}
.mtab .mto th{text-align:left;background:var(--soft);color:var(--ink);font-size:12px;letter-spacing:.04em}
.mtab .now{background:#FBF6EC}
.mtab input{width:62px;font:600 13px var(--mono);text-align:center;padding:6px 2px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink)}
.mtab td.now input{border-color:var(--ink)}.mtab input:disabled{background:transparent;border-style:dashed}
.kwk{display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line);padding-top:14px;margin-top:4px}
.kwr{display:grid;grid-template-columns:70px 150px minmax(0,1fr) 96px;gap:10px;align-items:center;padding:4px 6px;border-radius:8px}
.kwr.kwh{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--mut)}
.kwr.now{background:#FBF6EC}.kwr.lock .kwv{font-weight:600}.kwr .inp{min-width:0}
.kwk{max-height:none}
/* Build › The outcome: one compact row per key result, up to 3 targeted (Romain 2026-11-02) */
.kpg2{display:flex;flex-direction:column;gap:4px}.kpg2 .kpo{padding:4px 0 2px}
.kpl{display:grid;grid-template-columns:22px minmax(0,1fr) 100px 92px auto auto;gap:10px;align-items:center;border:1px solid var(--line);border-radius:10px;padding:6px 10px;background:var(--card)}
.kpl.on{background:var(--goldsoft);border-color:var(--gold)}.kpl.act{border-color:var(--ink);box-shadow:inset 3px 0 0 var(--gold)}
.kpb{width:22px;height:22px;border-radius:6px;border:1.5px solid #8E8A80;background:#fff;font-size:13px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:0}
.kpl.on .kpb{background:var(--ink);border-color:var(--ink);color:#fff}
.kpn{border:0;background:none;text-align:left;cursor:pointer;min-width:0;display:flex;gap:6px;align-items:baseline;font:inherit;font-size:13px;color:var(--ink);padding:2px 0}
.kpn b{font-family:var(--mono);font-size:12px;flex-shrink:0}.kpn span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.kpw2{display:flex;gap:6px;align-items:center;font-size:12px;color:var(--mut);min-width:0;overflow:hidden;white-space:nowrap}.kpv{font-size:12px;color:var(--mut);white-space:nowrap}
.kpon2{font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;background:var(--ink);color:var(--bg);border-radius:999px;padding:2px 8px;white-space:nowrap}
.kpx2{display:flex;gap:12px;flex-wrap:wrap;align-items:center;border-top:1px solid var(--line2);padding-top:10px}.kpd{display:inline-flex;gap:6px;align-items:center;font-size:13px}.kpd select{height:32px}
.krtabs{display:flex;gap:4px;padding:4px;background:var(--soft);border-radius:10px;width:fit-content;margin-bottom:10px}
.krtabs button{border:0;background:transparent;border-radius:8px;padding:6px 12px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;color:var(--ink2)}
.krtabs button[aria-selected="true"]{background:var(--ink);color:#fff}.krtabs button[aria-selected="true"] .note{color:#C9C4B7}
@container (max-width:900px){.kpl{grid-template-columns:26px minmax(0,1fr) auto}.kpl .kpw2,.kpl .kpv{display:none}}
.krsec{display:flex;flex-direction:column;gap:12px;padding-top:6px}.krsec+.krsec{border-top:2px solid var(--line);padding-top:18px;margin-top:6px}
.krsech{display:flex;gap:8px;align-items:center;font-size:14px}.krsech span:first-of-type{font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.krsech .sp{flex:1}
